    public static function applyAll():array{$out=[];foreach(self::prompts() as $slug=>$prompt){try{$a=AgentService::bySlug($slug);$out[$slug]=self::apply((int)$a['id'],$prompt,'CompanyOS 20 canonical active prompt');}catch(Throwable $e){$out[$slug]=['state'=>'skipped','error'=>Security::redactSecrets($e->getMessage(),180)];}}return $out;}
    public static function apply(int $agentId,string $prompt,string $summary):array{
        $a=AgentService::byId($agentId);$current=(string)$a['system_prompt'];$ver=0;
        if(trim($current)!==trim($prompt)){
            $q=db()->prepare('SELECT COUNT(*) FROM agent_prompt_versions WHERE agent_id=? AND prompt_text=?');$q->execute([$agentId,$current]);
            if((int)$q->fetchColumn()===0){$q=db()->prepare('SELECT COALESCE(MAX(version_no),0)+1 FROM agent_prompt_versions WHERE agent_id=?');$q->execute([$agentId]);$oldVer=(int)$q->fetchColumn();db()->prepare("INSERT INTO agent_prompt_versions(agent_id,version_no,prompt_text,change_summary,created_by_type,created_by_id) VALUES (?,?,?,?, 'system','companyos_20_canonicalizer')")->execute([$agentId,$oldVer,$current,'Archive of pre-20 active prompt before canonicalization']);}
            $q=db()->prepare('SELECT COALESCE(MAX(version_no),0)+1 FROM agent_prompt_versions WHERE agent_id=?');$q->execute([$agentId]);$ver=(int)$q->fetchColumn();db()->prepare("INSERT INTO agent_prompt_versions(agent_id,version_no,prompt_text,change_summary,created_by_type,created_by_id) VALUES (?,?,?,?, 'system','companyos_20_canonicalizer')")->execute([$agentId,$ver,$prompt,$summary]);db()->prepare('UPDATE agents SET system_prompt=? WHERE id=?')->execute([$prompt,$agentId]);
        }
        return ['state'=>'canonical','agent_id'=>$agentId,'slug'=>$a['slug'],'version_no'=>$ver];
    }
